// Normaliza el evento de WhatsApp Cloud API y decide la ruta: agente / no_texto / pausado.
// Ignora estados (enviado/entregado/leído) y mensajes duplicados que Meta reenvía.
const estado = $getWorkflowStaticData('global');
estado.procesados = estado.procesados || [];
estado.origenes = estado.origenes || {};
estado.pausados = estado.pausados || {};

const j = $input.first().json;
const v = j.entry ? (((j.entry[0] || {}).changes || [])[0] || {}).value || {} : j;
const msg = (v.messages || [])[0];
if (!msg) return [];                                   // es un aviso de estado, no un mensaje
if (estado.procesados.includes(msg.id)) return [];     // reenvío duplicado de Meta
estado.procesados.push(msg.id);
if (estado.procesados.length > 500) estado.procesados = estado.procesados.slice(-500);

const telefono = String(msg.from || '');
const contacto = (v.contacts || []).find(c => c.wa_id === telefono) || (v.contacts || [])[0] || {};
const nombre_perfil = (contacto.profile || {}).name || '';

let texto = '';
if (msg.type === 'text') texto = (msg.text || {}).body || '';
else if (msg.type === 'button') texto = (msg.button || {}).text || '';
else if (msg.type === 'interactive') {
  const i = msg.interactive || {};
  texto = (i.button_reply || {}).title || (i.list_reply || {}).title || '';
}

// Origen: anuncio Click-to-WhatsApp de Meta (referral) o código (ref: xxx) de nuestros enlaces.
// Se guarda la primera vez para que no se pierda en los mensajes siguientes.
const ref = ((texto.match(/\(ref:\s*([a-z0-9-]+)\)/i) || [])[1] || '').toLowerCase();
const referral = msg.referral;
if (referral) {
  estado.origenes[telefono] = `Anuncio Meta: ${referral.headline || referral.source_type || 'anuncio'}` +
    (referral.source_id ? ` (id ${referral.source_id})` : '');
} else if (ref && !estado.origenes[telefono]) {
  estado.origenes[telefono] = `Enlace: ${ref}`;
}
const origen = estado.origenes[telefono] || 'Directo / desconocido';

const textoCliente = texto.replace(/\(ref:[^)]*\)/gi, '').trim();
const pausado = Date.now() < (estado.pausados[telefono] || 0);
const esTexto = Boolean(textoCliente);

return [{
  json: {
    ruta: pausado ? 'pausado' : (esTexto ? 'agente' : 'no_texto'),
    telefono,
    nombre_perfil,
    origen,
    tipo: msg.type,
    texto_cliente: textoCliente,
    phone_number_id: (v.metadata || {}).phone_number_id || '',
    mensaje_para_agente:
      '[Contexto del sistema]\n' +
      `Nombre de perfil de WhatsApp: ${nombre_perfil || 'desconocido'}\n` +
      `Origen del contacto: ${origen}\n` +
      '[Fin del contexto del sistema]\n\n' +
      `Mensaje del cliente:\n${textoCliente}`,
  },
}];

