// Separa lo que ve el cliente de la evaluación interna del agente.
// El cliente NUNCA recibe score, clasificación ni marcas internas.
const HORAS_PAUSA_ESCALADO = 24;  // tiempo que el bot queda en silencio tras escalar a un humano

const prep = $('Preparar Mensaje').first().json;
const agente = $input.first().json;
const salida = String(agente.output || '');
const corte = salida.indexOf('<<<INTERNO>>>');
const visible = corte >= 0 ? salida.slice(0, corte) : salida;
const interno = corte >= 0 ? salida.slice(corte + '<<<INTERNO>>>'.length) : '';

let datos = {};
try {
  const bloque = (interno.match(/\{[\s\S]*\}/) || [''])[0];
  datos = JSON.parse(bloque);
} catch (e) {
  datos = { error_formato: true };
}

// Limpieza defensiva por si el modelo filtra marcas internas en la parte visible
let respuesta = visible
  .replace(/^\s*\[(SCORE|CLASIFICACI[OÓ]N|ACCI[OÓ]N_TOMADA)\].*$/gim, '')
  .replace(/ESCALAR_A_HUMANO/g, '')
  .trim();

const escalar = datos.escalar === true;
if (escalar) {
  const estado = $getWorkflowStaticData('global');
  estado.pausados = estado.pausados || {};
  estado.pausados[prep.telefono] = Date.now() + HORAS_PAUSA_ESCALADO * 3600 * 1000;
}

if (!respuesta) {
  respuesta = escalar
    ? 'Gracias por escribirnos. Una persona de nuestro equipo va a continuar esta conversación en breve.'
    : '¡Gracias por tu mensaje! ¿Me cuentas un poco más sobre lo que necesitas?';
}

return [{
  json: {
    telefono: prep.telefono,
    phone_number_id: prep.phone_number_id,
    nombre_perfil: prep.nombre_perfil,
    origen: prep.origen,
    texto_cliente: prep.texto_cliente,
    respuesta: respuesta.slice(0, 4000),  // límite de WhatsApp: 4096 caracteres
    score: datos.score ?? '',
    clasificacion: datos.clasificacion || 'SIN_DATOS',
    accion: datos.accion || '',
    motivo: datos.motivo || '',
    faltan: Array.isArray(datos.faltan) ? datos.faltan.join(', ') : '',
    escalar,
    error_formato: Boolean(datos.error_formato),
    pasos: JSON.stringify(agente.intermediateSteps || []).slice(0, 2000),
  },
}];

